/**
 * @summary Current Phase 7 Monte Carlo simulator validation status against real graded outcomes
 */
export const GetSimulatorValidationResponse = zod.object({
  "sampleSize": zod.number(),
  "minSampleSize": zod.number(),
  "simulatorAccuracy": zod.number().nullish(),
  "simulatorLogLoss": zod.number().nullish(),
  "simulatorBrier": zod.number().nullish(),
  "ensembleAccuracy": zod.number().nullish(),
  "ensembleLogLoss": zod.number().nullish(),
  "ensembleBrier": zod.number().nullish(),
  "adopted": zod.boolean(),
  "weight": zod.number(),
  "note": zod.string(),
  "computedAt": zod.coerce.date().nullish()
}).describe('Phase 7 simulator validation status against real graded outcomes -- honest either way, never silently adopted.')


/**
 * @summary Recompute the simulator's validation status from every real graded outcome currently available, and persist it
 */
export const RunSimulatorValidationResponse = zod.object({
  "sampleSize": zod.number(),
  "minSampleSize": zod.number(),
  "simulatorAccuracy": zod.number().nullish(),
  "simulatorLogLoss": zod.number().nullish(),
  "simulatorBrier": zod.number().nullish(),
  "ensembleAccuracy": zod.number().nullish(),
  "ensembleLogLoss": zod.number().nullish(),
  "ensembleBrier": zod.number().nullish(),
  "adopted": zod.boolean(),
  "weight": zod.number(),
  "note": zod.string(),
  "computedAt": zod.coerce.date().nullish()
}).describe('Phase 7 simulator validation status against real graded outcomes -- honest either way, never silently adopted.')


/**
 * @summary Lock predictions for newly-eligible upcoming fixtures, mark missed cutoffs, and grade completed matches
 */
export const RunPaperTradingCycleResponse = zod.object({
  "locked": zod.number(),
  "missed": zod.number(),
  "graded": zod.number(),
  "errors": zod.array(zod.string())
})


/**
 * @summary Recent invocations of the standalone paper-trading scheduled job, for monitoring gaps or failures
 */
export const listPaperTradingJobRunsQueryLimitDefault = 20;
export const listPaperTradingJobRunsQueryLimitMax = 100;



export const ListPaperTradingJobRunsQueryParams = zod.object({
  "limit": zod.coerce.number().min(1).max(listPaperTradingJobRunsQueryLimitMax).default(listPaperTradingJobRunsQueryLimitDefault)
})

export const ListPaperTradingJobRunsResponseItem = zod.object({
  "id": zod.number(),
  "jobName": zod.string(),
  "startedAt": zod.coerce.date(),
  "finishedAt": zod.coerce.date(),
  "status": zod.enum(['success', 'failed']),
  "attempts": zod.number(),
  "summary": zod.unknown().nullish(),
  "errorMessage": zod.string().nullish()
})
export const ListPaperTradingJobRunsResponse = zod.array(ListPaperTradingJobRunsResponseItem)


